mapper.select:
SELECT 
FROM work_calendar scoped
JOIN calendar_publication_timeline resolved_fact
  ON resolved_fact.work_calendar_id = scoped.work_calendar_id
JOIN work_calendar_version version
  ON version.work_calendar_version_id =
        resolved_fact.work_calendar_version_id
WHERE scoped.work_calendar_id = #{calendarId}
  AND resolved_fact.business_effective_from <= #{businessDate}
  AND resolved_fact.recorded_at <= #{knowledgeAsOf}
  AND resolved_fact.state = 'PUBLISHED'
  AND version.effective_from <= #{businessDate}
  AND version.effective_to > #{businessDate}
  AND NOT EXISTS (
      SELECT 1
      FROM calendar_publication_timeline newer
      WHERE newer.work_calendar_id = resolved_fact.work_calendar_id
        AND newer.business_effective_from <= #{businessDate}
        AND newer.recorded_at <= #{knowledgeAsOf}
        AND (
            newer.business_effective_from
                > resolved_fact.business_effective_from
            OR (
                newer.business_effective_from =
                    resolved_fact.business_effective_from
                AND newer.event_sequence > resolved_fact.event_sequence
            )
        )
  )
ORDER BY version.version_number, version.work_calendar_version_id

SELECT MIN(timeline.business_effective_from)
FROM calendar_publication_timeline timeline
WHERE timeline.work_calendar_id = #{calendarId}
  AND timeline.business_effective_from > #{after}
  AND timeline.recorded_at <= #{knowledgeAsOf}

SELECT COUNT(*)
FROM work_calendar_version version
WHERE version.work_calendar_id = #{calendarId}

SELECT DISTINCT FROM work_calendar scoped JOIN work_calendar_version version ON version.work_calendar_id = scoped.work_calendar_id AND version.version_number = ( SELECT MAX(latest.version_number) FROM work_calendar_version latest WHERE latest.work_calendar_id = scoped.work_calendar_id ) JOIN auth_principal_role_assignment role_assignment ON role_assignment.principal_id = #{principalId} JOIN auth_role_capability role_capability ON role_capability.role_id = role_assignment.role_id JOIN auth_capability capability ON capability.capability_id = role_capability.capability_id AND capability.capability_code = #{capability} JOIN auth_data_scope data_scope ON data_scope.scope_id = role_assignment.data_scope_id AND data_scope.scope_type = 'COMPANY' AND data_scope.company_id = scoped.company_id WHERE role_assignment.valid_from <= #{at} AND (role_assignment.valid_to IS NULL OR role_assignment.valid_to > #{at}) AND data_scope.valid_from <= #{at} AND (data_scope.valid_to IS NULL OR data_scope.valid_to > #{at}) AND (#{companyId} IS NULL OR scoped.company_id = #{companyId})
AND version.calendar_year = #{year}
ORDER BY version.calendar_year DESC, version.calendar_name, scoped.work_calendar_id LIMIT #{limit} OFFSET #{offset}

