mapper.select:
SELECT COALESCE(MAX(version_number), 0) + 1
FROM work_calendar_version
WHERE work_calendar_id = #{calendarId}

SELECT COALESCE(MAX(event_sequence), 0) + 1
FROM calendar_publication_timeline
WHERE work_calendar_id = #{calendarId}

SELECT 
FROM work_calendar_day calendar_day
JOIN work_calendar_version version
  ON version.work_calendar_version_id =
        calendar_day.work_calendar_version_id
JOIN work_calendar calendar
  ON calendar.work_calendar_id = version.work_calendar_id
WHERE calendar_day.work_calendar_version_id = #{calendarId}
  AND calendar_day.business_date >= #{from}
  AND calendar_day.business_date <= #{to}
ORDER BY calendar_day.business_date, calendar_day.work_calendar_day_id
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM work_calendar_day calendar_day
WHERE calendar_day.work_calendar_version_id = #{calendarId}
  AND calendar_day.business_date >= #{from}
  AND calendar_day.business_date <= #{to}

SELECT 
FROM work_calendar_day calendar_day
JOIN work_calendar_version version
  ON version.work_calendar_version_id =
        calendar_day.work_calendar_version_id
JOIN work_calendar calendar
  ON calendar.work_calendar_id = version.work_calendar_id
WHERE calendar_day.work_calendar_version_id = #{calendarId}
  AND calendar_day.business_date = #{businessDate}
  AND version.created_at <= #{knowledgeAsOf}
  AND calendar_day.created_at <= #{knowledgeAsOf}
